// Renders release notes for sample commits with the worktree's .releaserc.json.
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";

const root = "/Users/patrick/Sites/mcpsignals";
const require = createRequire(`${root}/package.json`);
const { generateNotes } = await import(require.resolve("@semantic-release/release-notes-generator"));
const rc = JSON.parse(readFileSync(`${root}/.claude/worktrees/go-sdk-84/.releaserc.json`, "utf8"));
const config = rc.plugins.find((p) => Array.isArray(p) && p[0] === "@semantic-release/release-notes-generator")[1];

const commits = [
  "feat(go): add official MCP SDK instrumentation",
  "fix(go): count events pushed after close as dropped",
  "perf(go): truncate strings without converting to runes",
  "fix(node): keep node fix visible",
  "feat: keep unscoped feature visible",
].map((message, i) => ({ hash: `${i}`.repeat(40), message }));

const notes = await generateNotes(config, {
  cwd: root,
  commits,
  lastRelease: { gitTag: "v1.0.0", version: "1.0.0" },
  nextRelease: { gitTag: "v1.1.0", version: "1.1.0" },
  options: { repositoryUrl: "https://github.com/zentered-studios/mcpsignals.git" },
  logger: { log() {} },
});
console.log(notes);

